class OrderFacade {
    private final InventoryService inventory;
    private final PaymentService payment;
    private final ShippingService shipping;
    private final EmailService email;

    String placeOrder(Cart cart, Customer c) {
        if (!inventory.reserve(cart.sku(), cart.qty())) throw new OutOfStockException();
        String orderId = payment.charge(c.id(), cart.total());
        shipping.schedule(orderId, c.address());
        email.sendReceipt(c.id(), orderId);
        return orderId;
    }
}
